using System;
using System.Collections.Generic;
using System.Text;

namespace Kentavr.SheetsToSO.Core
{
    /// <summary>
    /// Generates C# source text from header column definitions.
    /// Output uses '\n' line endings and 4-space indentation regardless of the OS.
    /// </summary>
    public static class CodeGenerator
    {
        /// <summary>Comment block placed at <see cref="CodeTemplates.HeaderPlaceholder"/>.</summary>
        public const string Header =
            "// <auto-generated>\n" +
            "// Generated by Kentavr.SheetsToSO. Do not edit manually: changes will be lost on the next generation.\n" +
            "// </auto-generated>";

        private const string MemberIndent = "        ";

        /// <summary>
        /// Generates the row class of a sheet: one public field per column, in column order.
        /// </summary>
        public static string GenerateRowClass(string className, IReadOnlyList<ColumnDefinition> columns, CodeGenOptions options)
        {
            ValidateName(className, nameof(className), "class name");
            if (columns == null)
                throw new ArgumentNullException(nameof(columns));
            if (options == null)
                throw new ArgumentNullException(nameof(options));

            var fields = new StringBuilder();
            for (var i = 0; i < columns.Count; i++)
            {
                var column = columns[i];
                if (column == null)
                    throw new ArgumentException($"Column at index {i} is null", nameof(columns));
                if (column.Name == className)
                    throw new ArgumentException(
                        $"Column '{column.Name}' has the same name as the class '{className}'", nameof(columns));

                if (fields.Length > 0)
                    fields.Append('\n');

                var type = column.Type;
                if (type.Kind == ColumnKind.Ref)
                {
                    fields.Append(MemberIndent)
                        .Append("// ").Append(type)
                        .Append(type.IsArray ? ": row ids in sheet " : ": row id in sheet ")
                        .Append(type.TypeName)
                        .Append('\n');
                }

                fields.Append(MemberIndent)
                    .Append("public ").Append(ToCSharpType(type)).Append(' ').Append(column.Name).Append(';');
            }

            return Render(options.RowClassTemplate, options.Namespace,
                CodeTemplates.ClassNamePlaceholder, className,
                CodeTemplates.FieldsPlaceholder, fields.ToString());
        }

        /// <summary>
        /// Generates an enum with the given members, in the given order.
        /// </summary>
        public static string GenerateEnum(string enumName, IReadOnlyList<string> members, CodeGenOptions options)
        {
            ValidateName(enumName, nameof(enumName), "enum name");
            if (members == null)
                throw new ArgumentNullException(nameof(members));
            if (options == null)
                throw new ArgumentNullException(nameof(options));

            var seen = new HashSet<string>(StringComparer.Ordinal);
            var text = new StringBuilder();
            for (var i = 0; i < members.Count; i++)
            {
                var member = members[i];
                if (member == null)
                    throw new ArgumentException($"Enum '{enumName}' member at index {i} is null", nameof(members));
                if (!CSharpIdentifier.IsIdentifier(member))
                    throw new ArgumentException(
                        $"Invalid enum '{enumName}' member '{member}': use Latin letters, digits and '_', not starting with a digit",
                        nameof(members));
                if (CSharpIdentifier.IsKeyword(member))
                    throw new ArgumentException(
                        $"Enum '{enumName}' member '{member}' is a reserved C# keyword", nameof(members));
                if (!seen.Add(member))
                    throw new ArgumentException($"Duplicate enum '{enumName}' member '{member}'", nameof(members));

                if (text.Length > 0)
                    text.Append('\n');
                text.Append(MemberIndent).Append(member).Append(',');
            }

            return Render(options.EnumTemplate, options.Namespace,
                CodeTemplates.EnumNamePlaceholder, enumName,
                CodeTemplates.MembersPlaceholder, text.ToString());
        }

        /// <summary>
        /// Returns unique enum names used by the columns, in order of first appearance.
        /// </summary>
        public static IReadOnlyList<string> CollectEnumNames(IReadOnlyList<ColumnDefinition> columns)
        {
            if (columns == null)
                throw new ArgumentNullException(nameof(columns));

            var seen = new HashSet<string>(StringComparer.Ordinal);
            var names = new List<string>();
            for (var i = 0; i < columns.Count; i++)
            {
                var column = columns[i];
                if (column == null)
                    throw new ArgumentException($"Column at index {i} is null", nameof(columns));
                if (column.Type.Kind == ColumnKind.Enum && seen.Add(column.Type.TypeName))
                    names.Add(column.Type.TypeName);
            }
            return names.AsReadOnly();
        }

        /// <summary>
        /// Generates the table class of a sheet: a <c>SheetTable&lt;&gt;</c> of the row class,
        /// plus the <c>ISheetRow</c> part of the row class (the row class must have a string field <c>id</c>).
        /// </summary>
        public static string GenerateTableClass(string tableClassName, string rowClassName, CodeGenOptions options)
        {
            ValidateName(tableClassName, nameof(tableClassName), "table class name");
            ValidateName(rowClassName, nameof(rowClassName), "row class name");
            if (options == null)
                throw new ArgumentNullException(nameof(options));
            if (tableClassName == rowClassName)
                throw new ArgumentException(
                    $"Table class name '{tableClassName}' must differ from the row class name", nameof(tableClassName));

            return Render(options.TableClassTemplate, options.Namespace,
                CodeTemplates.TableClassNamePlaceholder, tableClassName,
                CodeTemplates.RowClassNamePlaceholder, rowClassName);
        }

        /// <summary>
        /// Collects enum members from the data of <c>enum&lt;X&gt;</c> and <c>enum&lt;X&gt;[]</c> columns:
        /// unique values in order of first appearance (sheets in order, rows top to bottom, columns left to right).
        /// Every enum used by a column is present, with no members when none of its cells has a value.
        /// A value that is not a valid C# name is an error in the result, not an exception.
        /// </summary>
        public static EnumMembersResult CollectEnumMembers(IReadOnlyList<SheetParseResult> sheets)
        {
            if (sheets == null)
                throw new ArgumentNullException(nameof(sheets));

            var names = new List<string>();
            var members = new Dictionary<string, List<string>>(StringComparer.Ordinal);
            var seen = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
            var errors = new List<SheetError>();

            for (var s = 0; s < sheets.Count; s++)
            {
                var sheet = sheets[s];
                if (sheet == null)
                    throw new ArgumentException($"Sheet at index {s} is null", nameof(sheets));

                var enumColumns = new List<ColumnDefinition>();
                foreach (var column in sheet.Columns)
                {
                    if (column.Type.Kind != ColumnKind.Enum)
                        continue;
                    enumColumns.Add(column);
                    var enumName = column.Type.TypeName;
                    if (!members.ContainsKey(enumName))
                    {
                        names.Add(enumName);
                        members.Add(enumName, new List<string>());
                        seen.Add(enumName, new HashSet<string>(StringComparer.Ordinal));
                    }
                }

                if (enumColumns.Count == 0)
                    continue;

                foreach (var row in sheet.Rows)
                {
                    foreach (var column in enumColumns)
                    {
                        if (!row.Values.TryGetValue(column.Name, out var value) || value == null)
                            continue;

                        var address = CellAddress.ToA1(column.ColumnIndex, row.RowNumber);
                        if (value is string[] elements)
                        {
                            for (var i = 0; i < elements.Length; i++)
                                AddEnumMember(sheet.SheetName, column, elements[i], $"element {i + 1} '{elements[i]}'",
                                    address, members, seen, errors);
                        }
                        else if (value is string text)
                        {
                            AddEnumMember(sheet.SheetName, column, text, $"'{text}'", address, members, seen, errors);
                        }
                    }
                }
            }

            var result = new Dictionary<string, IReadOnlyList<string>>(StringComparer.Ordinal);
            foreach (var pair in members)
                result.Add(pair.Key, pair.Value.AsReadOnly());
            return new EnumMembersResult(names.AsReadOnly(), result, errors.AsReadOnly());
        }

        private static void AddEnumMember(string sheetName, ColumnDefinition column, string value, string subject,
            string address, Dictionary<string, List<string>> members, Dictionary<string, HashSet<string>> seen,
            List<SheetError> errors)
        {
            if (string.IsNullOrEmpty(value))
                return;

            var enumName = column.Type.TypeName;
            if (!CSharpIdentifier.IsValidName(value))
            {
                errors.Add(new SheetError(sheetName, new CellError(CellErrorCode.InvalidEnumValue, address,
                    $"Column '{column.Name}': {subject} is not a valid enum '{enumName}' value: " +
                    "use Latin letters, digits and '_', not starting with a digit, and not a C# keyword")));
                return;
            }

            if (seen[enumName].Add(value))
                members[enumName].Add(value);
        }

        private static string ToCSharpType(ColumnType type)
        {
            string baseName;
            switch (type.Kind)
            {
                case ColumnKind.String: baseName = "string"; break;
                case ColumnKind.Int: baseName = "int"; break;
                case ColumnKind.Float: baseName = "float"; break;
                case ColumnKind.Bool: baseName = "bool"; break;
                case ColumnKind.Enum: baseName = type.TypeName; break;
                case ColumnKind.Ref: baseName = "string"; break;
                default: throw new ArgumentOutOfRangeException(nameof(type), type.Kind, "Unknown column kind");
            }
            return type.IsArray ? baseName + "[]" : baseName;
        }

        private static void ValidateName(string value, string paramName, string what)
        {
            if (value == null)
                throw new ArgumentNullException(paramName);
            if (!CSharpIdentifier.IsIdentifier(value))
                throw new ArgumentException(
                    $"Invalid {what} '{value}': use Latin letters, digits and '_', not starting with a digit", paramName);
            if (CSharpIdentifier.IsKeyword(value))
                throw new ArgumentException($"The {what} '{value}' is a reserved C# keyword", paramName);
        }

        private static string Render(string template, string @namespace,
            string namePlaceholder, string name, string bodyPlaceholder, string body)
        {
            // Templates may come from files with CRLF endings; output is always '\n'.
            return template
                .Replace("\r\n", "\n")
                .Replace('\r', '\n')
                .Replace(CodeTemplates.HeaderPlaceholder, Header)
                .Replace(CodeTemplates.NamespacePlaceholder, @namespace)
                .Replace(namePlaceholder, name)
                .Replace(bodyPlaceholder, body);
        }
    }
}
